import 'package:flutter/material.dart';

class StackExample extends StatelessWidget {
  const StackExample({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Column(
        children: [
          Stack(
            clipBehavior: Clip.none,
            children: [
              Image.network("data:image/jpeg;base64,"),

              const Positioned(
                bottom: -40,
                right: 10,
                child: CircleAvatar(
                  radius: 40,
                ),
              ),
              Positioned(
                bottom: -100,
                right: 5,
                child: Container(
                  height: 100,
                  width: 100,
                  color: Colors.blue,
                ),
              ),
            ]
          ),
        ],
      ),
    );
  }

}